    "sql_solution": "WITH flagged_rides AS (\n  SELECT \n    ride_id, rider_id, status, request_time,\n    LAG(status) OVER (PARTITION BY rider_id ORDER BY request_time) AS prev_status,\n    LAG(request_time) OVER (PARTITION BY rider_id ORDER BY request_time) AS prev_time\n  FROM rides\n)\nSELECT DISTINCT rider_id\nFROM flagged_rides\nWHERE status = 'cancelled'\n  AND prev_status = 'cancelled'\n  AND request_time <= prev_time + INTERVAL '60 minutes';",
    "common_mistake": "Option B ignores event ordering: a rider could have cancelled in January and again in June with 50 completed rides in between.",
    "learning_point": "LAG(column, 1) OVER (PARTITION BY entity ORDER BY timestamp) lets you inspect the exact prior event in sequential event logs."
