    "sql_solution": "WITH customer_cohort AS (\n  SELECT \n    customer_id, \n    MIN(order_date) AS first_order_date\n  FROM orders\n  GROUP BY customer_id\n)\nSELECT \n  o.order_id,\n  o.customer_id,\n  o.order_date,\n  o.amount,\n  CASE \n    WHEN o.order_date = c.first_order_date THEN 'New'\n    ELSE 'Returning'\n  END AS customer_type\nFROM orders o\nINNER JOIN customer_cohort c \n  ON o.customer_id = c.customer_id;",
