    "option_a": "WITH weekly AS (SELECT DATE_TRUNC('week', send_date) as wk, 100.0 * SUM(clicks) / SUM(emails_sent) as ctr FROM email_blasts GROUP BY 1) SELECT wk, ctr, ctr - LAG(ctr) OVER (ORDER BY wk) as wow_change FROM weekly;",
    "option_b": "SELECT send_date, (clicks/emails_sent) - LAG(clicks/emails_sent) OVER () FROM email_blasts;",
