    "question": "Which query correctly extracts the top rider per calendar year?",
    "option_a": "WITH yearly_counts AS (SELECT EXTRACT(YEAR FROM trip_time) as yr, rider_id, COUNT(*) as trip_count, DENSE_RANK() OVER (PARTITION BY EXTRACT(YEAR FROM trip_time) ORDER BY COUNT(*) DESC) as rnk FROM completed_trips GROUP BY 1, 2) SELECT yr, rider_id, trip_count FROM yearly_counts WHERE rnk = 1 ORDER BY yr ASC;",
    "option_b": "SELECT EXTRACT(YEAR FROM trip_time), rider_id, MAX(COUNT(*)) FROM completed_trips GROUP BY 1, 2;",
